#!/usr/bin/env python3
"""blueprint.py — assemble the Blueprint package from a breakdown. Pure code.

The blueprint is the factory's *reproducible product* (ADR-0002): held in
`.blueprint/<source>/`, byte-identical per (design, factory-version), never the
app. This stage reads a breakdown.json (+ optional W3C DTCG tokens.json) and
emits the full package: metadata (manifest + golden), the build playbook, a
pubspec fragment, and the platform-detecting Dart CORE skeleton as templates.

One codebase, three render strategies (ADR / CONTEXT "Render strategy"):
glass (iOS), expressive (Android), shadcn (web+desktop). The core is the shared
spine; per-platform native glue is the BUILDER's job (#17), NOT emitted here.

Two template layers (ADR-0002 "Generated layer" / "Extension point"):
  - generated    — factory-owned, regenerated freely, byte-identical, never
                   hand-edited (app shell, router, locator wiring, render
                   resolver, DDD shell + Ports + Supabase base, token layer,
                   pubspec). First line marker: `AUTO-GENERATED by flutter_crew`.
  - extension    — emitted ONCE as a stable stub, never rewritten; where the
                   operator/builder puts business logic + widget bodies (one
                   View + ViewModel per screen). First line marker:
                   `FACTORY EXTENSION POINT` + `@appbox-extension-point: <id>`.

Determinism: pure string templating, sorted keys, no wall-clock (timestamp via
--generated). Same breakdown + same tokens + same factory-version ⇒ same bytes.

Usage:
    blueprint.py <breakdown.json> <out-dir> [--tokens tokens.json]
                 [--factory-version V] [--generated ISO8601] [--stack stacked]
"""
import hashlib
import html
import json
import os
import re
import sys

FACTORY_VERSION = "0.1.0"
TEMPLATES_VERSION = "36"   # bump when any template changes → golden shifts

GEN_MARKER = "// AUTO-GENERATED by flutter_crew (factory). Do not edit — regenerate."
EXT_MARKER = "// FACTORY EXTENSION POINT — hand-edit freely; the factory will NOT overwrite this file."
GEN_MARKER_YAML = "# AUTO-GENERATED by flutter_crew (factory). Do not edit — regenerate."  # YAML uses # not //

# Brand sign-in glyphs — a PRINCIPLED, GENERALIZED registry. Each brand's official
# mark is the single source of truth; the pipeline rasterizes it once to a PNG (via
# rsvg-convert) and every native platform renders that SAME asset (iOS UIKit decode +
# Android Compose BitmapPainter), so iOS and Android render byte-identical marks with
# no per-platform redraw. Adding a brand = one row; no Dart/Kotlin branch, no Canvas
# bezier, no new dep.
#
# colorMode drives the per-brand RENDER rule, dictated by each brand's OWN guidelines
# (applied identically on every platform — NOT a per-platform override):
#   "brand" → render the mark in its fixed brand colors as-is (Google multi-color G
#             is MANDATED: "Don't use monochrome" — developers.google.com/identity/
#             branding-guidelines; Microsoft: "Don't make the logo a single color").
#   "mono"  → render monochrome, tinted to the button foreground. The SVG uses
#             fill="currentColor" → rsvg bakes black → tinted at render (Apple has no
#             multi-color mark — HIG mandates the official logo file, black or white;
#             GitHub/X brand rules permit mono). The "beautiful black Google" mono
#             variant is intentionally NOT offered: it violates Google's guidelines.
_BRAND_REGISTRY = {
    "google": {
        "displayName": "Google", "colorMode": "brand",
        # platforms: where this provider's native sign-in EXISTS. Mirrors the
        # canonical catalog's providerPlatformBindings — the single source of truth
        # for platform-incompatible primitives. google_sign_in ships for all 3.
        "platforms": ["ios", "android", "web"],
        # The official 4-color G (brand-mandated; Google's published path data).
        "svg": ('<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18">'
                '<path d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 01-1.8 2.72v2.26h2.91c1.7-1.57 2.69-3.88 2.69-6.62z" fill="#4285F4"/>'
                '<path d="M9 18c2.43 0 4.47-.81 5.96-2.18l-2.91-2.26c-.81.54-1.84.86-3.05.86-2.34 0-4.33-1.58-5.04-3.7H.96v2.33A9 9 0 009 18z" fill="#34A853"/>'
                '<path d="M3.96 10.72a5.4 5.4 0 010-3.44V4.95H.96a9 9 0 000 8.1l3-2.33z" fill="#FBBC04"/>'
                '<path d="M9 3.58c1.32 0 2.5.45 3.44 1.35l2.58-2.59C13.46.89 11.43 0 9 0A9 9 0 00.96 4.95l3 2.33C4.67 5.16 6.66 3.58 9 3.58z" fill="#EA4335"/>'
                '</svg>'),
    },
    "apple": {
        "displayName": "Apple", "colorMode": "mono",
        # Apple Sign-In is iOS/macOS only (sign_in_with_apple plugin). Suppress on
        # Android/web — the runtime AdaptiveAuthButton consults _kProviderPlatforms
        # (generated from this field) rather than a hardcoded provider name.
        "platforms": ["ios"],
        # The Apple logo silhouette (monochrome; currentColor → tinted to button fg).
        "svg": ('<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18">'
                '<path fill="currentColor" d="M13.4 9.6c0-1.9 1.5-2.8 1.6-2.9-.9-1.3-2.2-1.5-2.7-1.5-1.2-.1-2.2.7-2.8.7-.6 0-1.5-.7-2.4-.7-1.3 0-2.4.7-3 1.9-1.3 2.2-.3 5.5 1 7.3.6.9 1.3 1.9 2.3 1.8.9 0 1.3-.6 2.4-.6s1.4.6 2.4.6c1 0 1.6-.9 2.2-1.8.7-1 .9-2 .9-2-.1 0-1.9-.7-1.9-2.8zM11.7 4.1c.5-.6.8-1.4.7-2.2-.7 0-1.5.5-2 1.1-.5.5-.9 1.3-.8 2.1.8 0 1.6-.4 2.1-1z"/>'
                '</svg>'),
    },
    # Seeded rows for brands the current designs don't use yet — fill the svg + drop
    # the placeholder when a design references them (detection is by breakdown
    # props.name matching a registry key). A row without an svg is skipped at emit.
    # `platforms` defaults to all-3 when absent (see _provider_platforms); set it
    # explicitly for a platform-bound provider (e.g. a web-only OAuth → ["web"]).
    "microsoft": {"displayName": "Microsoft", "colorMode": "brand", "svg": None},
    "facebook":  {"displayName": "Facebook",  "colorMode": "brand", "svg": None},
    "github":    {"displayName": "GitHub",    "colorMode": "mono",  "svg": None},
    "x":         {"displayName": "X",         "colorMode": "mono",  "svg": None},
}


def _rasterize_svg(svg, size=54):
    """Rasterize a brand-glyph SVG to PNG bytes via `rsvg-convert` (librsvg).
    PNG is the format native UIKit decodes directly (no SVGKit multi-path bug)
    and Android loads as a Bitmap — so the official 4-color Google G renders
    identically on both platforms from one asset. Rasterized once at 3× (54px)
    so it downscales crisply to 18pt on retina (no @2x/@3x sprawl).
    For mono marks, rsvg resolves fill="currentColor" to black; the tint is
    applied at render via the platform color-filter. Raises RuntimeError if
    rsvg-convert is absent (the factory requires `brew install librsvg`)."""
    import subprocess, tempfile, os
    with tempfile.NamedTemporaryFile(suffix=".svg", delete=False) as tf:
        tf.write(svg.encode("utf-8")); svg_path = tf.name
    png_path = svg_path[:-4] + ".png"
    try:
        r = subprocess.run(["rsvg-convert", "-w", str(size), "-h", str(size),
                            svg_path, "-o", png_path],
                           capture_output=True, timeout=15)
        if r.returncode != 0 or not os.path.isfile(png_path):
            raise RuntimeError("rsvg-convert failed: %s" % (r.stderr.decode("utf-8", "ignore").strip()
                                                            or "no output"))
        with open(png_path, "rb") as f:
            return f.read()
    finally:
        for p in (svg_path, png_path):
            if os.path.exists(p):
                os.unlink(p)


def _detected_brands(breakdown):
    """Scan the breakdown for brand-glyph primitives (props.name in the registry).
    The design emits <GoogleGlyph>/<AppleGlyph> (or equivalent) which the parse
    stage records as a primitive with props.name='google'/'apple'. Only brands the
    DESIGN actually uses get assets emitted (no dead assets for unused rows)."""
    found = set()
    def walk(o):
        if isinstance(o, dict):
            p = o.get("props")
            if isinstance(p, dict) and p.get("name") in _BRAND_REGISTRY:
                found.add(p["name"])
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    walk(breakdown)
    return sorted(found)


def _brand_color_mode(name):
    """The colorMode for a brand ('brand' | 'mono') — used by the Dart + Kotlin
    templates to decide whether to tint the glyph to the button foreground."""
    return _BRAND_REGISTRY.get(name, {}).get("colorMode", "brand")


def _emit_brand_pngs(gen, detected):
    """Emit one rasterized brand-glyph PNG per DETECTED brand into the generated
    layer. brand_{name}.png is the canonical asset every native platform renders
    (iOS UIKit decode, Android Compose BitmapPainter) — one source, identical
    output. The SVG sibling (assets/svg/brand_{name}.svg) feeds the shadcn/web
    path (SvgPicture renders SVG correctly in-browser). Loud degrade if
    rsvg-convert is absent — a silently-blank glyph is the bug this fixes."""
    emitted = []
    try:
        for name in detected:
            entry = _BRAND_REGISTRY.get(name)
            if not entry or not entry.get("svg"):
                continue  # seeded-but-unfilled row (e.g. microsoft) — skip, don't crash
            gen[f"assets/png/brand_{name}.png"] = _rasterize_svg(entry["svg"])
            gen[f"assets/svg/brand_{name}.svg"] = entry["svg"]
            emitted.append(name)
    except (RuntimeError, FileNotFoundError) as e:
        # ponytail: degrade loudly, not silently — a blank glyph shipped undetected
        # is the exact bug this fixes. If rsvg-convert is absent, the factory MUST
        # surface it so the operator installs librsvg before the next run.
        sys.stderr.write("WARN: brand PNG rasterization skipped (%s) — "
                         "run `brew install librsvg`, then re-generate\n" % e)
    return emitted

