def _pascal(s: str) -> str:
    parts = [p for p in re.split(r"[^0-9a-zA-Z]+", s) if p]
    if not parts:
        return "Screen"
    parts[0] = re.sub(r"^[^a-zA-Z]+", "", parts[0]) or "S"
    return "".join(p[:1].upper() + p[1:] for p in parts)


def _snake(s: str) -> str:
    s = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", s)
    s = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", s)
    return re.sub(r"[^0-9a-zA-Z]+", "_", s).strip("_").lower() or "screen"


def _design_title(source: str) -> str:
    """First <title> text from the design HTML, '' if absent/unreadable.

    ponytail: <title> is where the design declares its brand (e.g.
    'Atlet — Workout app'); reading it beats naming the app after the source
    file's directory (which gave 'bundle' for atlet). Returns '' on a missing
    file or no <title> so callers fall back to the basename — never throws,
    blueprint must stay deterministic given a frozen breakdown.
    """
    try:
        with open(source, encoding="utf-8", errors="replace") as f:
            text = f.read()
    except OSError:
        return ""
    m = re.search(r"<title[^>]*>(.*?)</title>", text, re.I | re.S)
    return html.unescape(m.group(1)).strip() if m else ""


def _brand_segment(raw: str) -> str:
    """'Atlet — Workout app' → 'Atlet': the brand word before a subtitle split."""
    # ponytail: split on common title separators; brand is the first segment.
    return re.split(r"\s+[—:\-|·;]\s+", raw, maxsplit=1)[0].strip() or raw.strip()


def _app_display_name(source: str, override: str = None) -> str:
    """Human-readable app name for platform display manifests (iOS/android/web).

    Priority: operator --app-name → design <title> brand (case preserved) →
    Title-cased source basename.
    """
    if override and override.strip():
        return override.strip()
    title = _design_title(source)
    seg = _brand_segment(title) if title else ""
    if seg:
        return seg
    base = re.sub(r"\.(html|jsx|tsx)$", "", os.path.basename(source or "App"), flags=re.I)
    return base.strip().title() or "Crew App"


def _app_name(source: str, override: str = None) -> str:
    """Dart-package-safe slug for pubspec `name:` + manifest appName.

    Priority: operator --app-name → design <title> brand → source basename.
    Lowercase, underscore-separated (pub requires ^[a-z][a-z0-9_]*$).
    """
    if override and override.strip():
        raw = override.strip()
    else:
        title = _design_title(source)
        raw = _brand_segment(title) if title else re.sub(
            r"\.(html|jsx|tsx)$", "", os.path.basename(source or "app"), flags=re.I)
    return re.sub(r"[^0-9a-zA-Z]+", "_", raw).strip("_").lower() or "crew_app"


