# --------------------------------------------------------------------------- #
# backend config resolver (ADR-0013) — auth methods are design-derived ∪ config
# --------------------------------------------------------------------------- #

_BACKEND_AUTH_DEFAULT = ("password", "emailOtp")  # mirrors schema backend.auth.methods default
# Maps a captured go('<provider>') auth dispatcher to a canonical method id.
# ponytail: heuristic — recognizes only the go('...') dispatch the capture emits;
# a design with a different auth dispatcher declares backend.auth.methods in config.
_GO_TOKEN_METHOD = {
    "google": "googleOAuth", "apple": "appleOAuth",
    "email": "emailOtp", "magic": "magicLink", "password": "password",
}


def _derive_auth_methods(handlers: dict) -> list:
    """Scan captured handlers for go('<provider>') auth dispatchers → methods."""
    blob = json.dumps(handlers or {})
    found = {m for tok, m in _GO_TOKEN_METHOD.items()
             if f"go('{tok}')" in blob or f'go("{tok}")' in blob}
    return sorted(found)


def _backend_cfg(config: dict = None, handlers: dict = None) -> dict:
    """Resolve the backend block (ADR-0013): auth.methods = design-derived ∪
    explicit config, falling back to the schema default when neither is present.
    Returns a flat dict the templates consume (authMethods/offlineMode/...)."""
    backend = (config or {}).get("backend") or {}
    derived = _derive_auth_methods(handlers)
    cfg_methods = (backend.get("auth") or {}).get("methods")
    methods = sorted(set(derived) | set(cfg_methods or [])) or list(_BACKEND_AUTH_DEFAULT)
    return {
        "provider": backend.get("provider", "supabase"),
        "authMethods": methods,
        "offlineMode": (backend.get("offline") or {}).get("mode", "off"),
        "target": backend.get("target", "local"),
    }


def _auth_method_dart(methods) -> str:
    """The supabase_flutter-only auth methods gated by the resolved set. Native
    OAuth (google/apple) is emitted in the OAuth slice — it needs the
    google_sign_in v7 / sign_in_with_apple API verified against current docs +
    real client IDs (out-of-band, like the offline `sync` mode); the headless
    smoke uses the SMOKE_AUTOLOGIN password backdoor, so it is not on this path."""
    m = set(methods or ())
    out = []
    if "emailOtp" in m:
        out.append("""
  /// Email OTP (ADR-0003): emails a one-time code to [email] (no deep link).
  Future<void> sendEmailOtp({required String email}) =>
      Supabase.instance.client.auth.signInWithOtp(email: email);

  /// Verifies the emailed OTP [token]; on success a session is established.
  Future<AuthResponse> verifyEmailOtp(
          {required String email, required String token}) =>
      Supabase.instance.client.auth
          .verifyOTP(email: email, token: token, type: OtpType.email);""")
    if "magicLink" in m:
        out.append("""
  /// Magic link (ADR-0003): emails a sign-in link; completion arrives via the
  /// deep link in capabilityConfig.deepLinks.scheme.
  Future<void> sendMagicLink({required String email, String? redirectTo}) =>
      Supabase.instance.client.auth
          .signInWithOtp(email: email, emailRedirectTo: redirectTo);""")
    if "googleOAuth" in m:
        out.append("""
  /// Native Google sign-in (google_sign_in v7): gets an idToken from Google, then
  /// exchanges it with Supabase (signInWithIdToken). Client IDs are supplied
  /// out-of-band via --dart-define — GOOGLE_SERVER_CLIENT_ID is the WEB client id
  /// (== the idToken audience == Supabase "Authorized Client IDs"; the #1 native
  /// misconfig), GOOGLE_IOS_CLIENT_ID is the iOS client id. Unconfigured → throws a
  /// clear AuthException that the ViewModel surfaces; it never crashes the app.
  /// See docs/plans/operator-auth-setup.md.
  Future<AuthResponse> signInWithGoogle() async {
    const webClientId = String.fromEnvironment('GOOGLE_SERVER_CLIENT_ID');
    const iosClientId = String.fromEnvironment('GOOGLE_IOS_CLIENT_ID');
    if (webClientId.isEmpty) {
      throw const AuthException(
          'Google sign-in not configured. Pass '
          '--dart-define=GOOGLE_SERVER_CLIENT_ID=<web client id> '
          '(and GOOGLE_IOS_CLIENT_ID on iOS). See docs/plans/operator-auth-setup.md.');
    }
    final google = GoogleSignIn.instance;
    await google.initialize(
        serverClientId: webClientId,
        clientId: iosClientId.isEmpty ? null : iosClientId);
    final account = await google.authenticate();
    final idToken = account.authentication.idToken;
    if (idToken == null) {
      throw const AuthException('Google sign-in returned no idToken.');
    }
    // v7 split auth from authorization: the accessToken comes from the
    // authorization client, not the authentication object.
    const scopes = ['email', 'profile'];
    final authz =
        await account.authorizationClient.authorizationForScopes(scopes) ??
            await account.authorizationClient.authorizeScopes(scopes);
    return Supabase.instance.client.auth.signInWithIdToken(
      provider: OAuthProvider.google,
      idToken: idToken,
      accessToken: authz.accessToken,
    );
  }""")
    if "appleOAuth" in m:
        out.append("""
  /// Native Apple sign-in (sign_in_with_apple ^8.1.0): the nonce contract is
  /// sha256(raw) → Apple, raw → Supabase. iOS uses the native sheet (requires the
  /// "Sign in with Apple" capability); Android/web use the web flow when
  /// APPLE_SERVICE_ID + APPLE_REDIRECT_URI are supplied via --dart-define.
  /// See docs/plans/operator-auth-setup.md.
  Future<AuthResponse> signInWithApple() async {
    final rawNonce = Supabase.instance.client.auth.generateRawNonce();
    final hashedNonce = sha256.convert(utf8.encode(rawNonce)).toString();
    const serviceId = String.fromEnvironment('APPLE_SERVICE_ID');
    const redirect = String.fromEnvironment('APPLE_REDIRECT_URI');
    final credential = await SignInWithApple.getAppleIDCredential(
      scopes: const [
        AppleIDAuthorizationScopes.email,
        AppleIDAuthorizationScopes.fullName,
      ],
      nonce: hashedNonce,
      webAuthenticationOptions: serviceId.isEmpty
          ? null
          : WebAuthenticationOptions(
              clientId: serviceId, redirectUri: Uri.parse(redirect)),
    );
    final idToken = credential.identityToken;
    if (idToken == null) {
      throw const AuthException('Apple sign-in returned no identityToken.');
    }
    return Supabase.instance.client.auth.signInWithIdToken(
      provider: OAuthProvider.apple,
      idToken: idToken,
      nonce: rawNonce,
    );
  }""")
    return "\n".join(out)


def _tpl_supabase_auth(methods=_BACKEND_AUTH_DEFAULT) -> str:
    extra = _auth_method_dart(methods)
    m = set(methods or ())
    dart_imports, pkg_imports = [], ["import 'package:supabase_flutter/supabase_flutter.dart';"]
    if "googleOAuth" in m:
        pkg_imports.append("import 'package:google_sign_in/google_sign_in.dart';")
    if "appleOAuth" in m:
        dart_imports.append("import 'dart:convert';")
        pkg_imports += [
            "import 'package:crypto/crypto.dart';",
            "import 'package:sign_in_with_apple/sign_in_with_apple.dart';",
        ]
    import_block = "\n".join(dart_imports + sorted(pkg_imports))
    return f"""{GEN_MARKER}
{import_block}

/// Supabase auth service (ADR-0003). Locator-injected into ViewModels. Methods
/// are gated by backend.auth.methods (design-derived ∪ config); signInWithPassword
/// is always present as the SMOKE_AUTOLOGIN backdoor (compile-time, tree-shaken).
class SupabaseAuthService {{
  User? get currentUser => Supabase.instance.client.auth.currentUser;
  Stream<AuthState> get authState =>
      Supabase.instance.client.auth.onAuthStateChange;

  Future<AuthResponse> signInWithPassword(
          {{required String email, required String password}}) =>
      Supabase.instance.client.auth
          .signInWithPassword(email: email, password: password);

  Future<AuthResponse> signUp(
          {{required String email, required String password}}) =>
      Supabase.instance.client.auth.signUp(email: email, password: password);
{extra}

  Future<void> signOut() => Supabase.instance.client.auth.signOut();
}}
"""


def _tpl_base_repo() -> str:
    return f"""{GEN_MARKER}
import 'package:supabase_flutter/supabase_flutter.dart';

/// Base adapter: maps a domain Port to a Supabase table (ADR-0003). Per-entity
/// repositories extend this AND implement their domain Port.
abstract class BaseSupabaseRepository {{
  SupabaseClient get client => Supabase.instance.client;
  String get table;

  Future<List<Map<String, dynamic>>> allRows() => client.from(table).select();
  Future<Map<String, dynamic>?> rowById(Object id) =>
      client.from(table).select().eq('id', id).maybeSingle();
  Future<Map<String, dynamic>> insertRow(Map<String, dynamic> row) =>
      client.from(table).insert(row).select().single();
  Future<Map<String, dynamic>> updateRow(
          Object id, Map<String, dynamic> row) =>
      client.from(table).update(row).eq('id', id).select().single();
  Future<void> deleteRow(Object id) => client.from(table).delete().eq('id', id);
}}
"""


def _dep_line(name: str, spec) -> str:
    """One pubspec dependency entry. `spec` is a version string for hosted
    packages; a dict (e.g. {"sdk": "flutter"}) renders as a nested entry —
    the same shape the literal `flutter: sdk: flutter` above uses."""
    if isinstance(spec, dict):
        inner = "\n".join(f"    {sk}: {sv}" for sk, sv in spec.items())
        return f"  {name}:\n{inner}"
    return f"  {name}: {spec}"


def _tpl_pubspec(app_name: str, source: str, methods=_BACKEND_AUTH_DEFAULT) -> str:
    m = set(methods or ())
    pkgs = dict(PUBSPEC_DEPS)
    if "googleOAuth" in m:
        pkgs["google_sign_in"] = "^7.2.0"      # native Google idToken (v7 API; Dart ^3.7 floor)
    if "appleOAuth" in m:
        pkgs["sign_in_with_apple"] = "^8.1.0"  # native Apple credential
        pkgs["crypto"] = "^3.0.7"              # sha256 nonce (Apple nonce contract)
    deps = "\n".join(_dep_line(k, v) for k, v in sorted(pkgs.items()))
    dev = "\n".join(f"  {k}: {v}" for k, v in sorted(PUBSPEC_DEV.items()))
    return f"""{GEN_MARKER_YAML}
name: {app_name}
description: Generated by flutter_crew (factory) from {os.path.basename(source or '')}.
publish_to: 'none'
version: 0.1.0+1

environment:
  sdk: ^3.7.0

dependencies:
  flutter:
    sdk: flutter
{deps}

dev_dependencies:
  flutter_test:
    sdk: flutter
{dev}

flutter:
  uses-material-design: true
  generate: true  # gen-l10n on pub get (no-op when the app has no l10n.yaml)
"""


def _tpl_analysis_options() -> str:
    # `exclude:` keeps the analyzer off the blueprint-package `templates/` dir
    # (an intermediate that the older manual relay wrote into the target — never
    # part of the shipped app) and the stale `flutter create` widget_test.dart
    # default (references MyApp; the generated app is CrewApp). Without this,
    # both poison `dart analyze` with uri_does_not_exist / undefined_* errors
    # that have nothing to do with the generated app and block the G5 gate.
    return f"""{GEN_MARKER_YAML}
include: package:flutter_lints/flutter.yaml

analyzer:
  exclude:
    - templates/**
    - test/widget_test.dart

linter:
  rules:
    avoid_print: true
    prefer_const_constructors: true
    prefer_const_declarations: true
"""


