def _load_tokens_dart(tokens_path):
    """Return app_tokens.dart source from a W3C DTCG tokens.json (reuse
    transform_tokens.emit_dart), or None."""
    if not tokens_path or not os.path.exists(tokens_path):
        return None
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        from transform_tokens import emit_dart  # reuse, no duplication
        with open(tokens_path, encoding="utf-8") as f:
            tree = json.load(f)
        return emit_dart(tree)
    except Exception as e:  # pragma: no cover — degrade gracefully
        print(f"blueprint: tokens transform skipped ({e})", file=sys.stderr)
        return None


def _tokens_stub() -> str:
    return f"""{GEN_MARKER}
import 'package:flutter/material.dart';

/// Token layer (ADR-0002 #4): the ONLY thing identical across platforms.
/// Run extract_tokens → transform_tokens on the design to populate this file,
/// or pass --tokens to blueprint.py. Until then these are empty placeholders.
abstract final class AppTokens {{}}
"""


def _golden(breakdown: dict, tokens_tree: dict, data_model: dict) -> str:
    payload = json.dumps(
        {
            "pages": breakdown.get("pages", []),
            "screenFlow": breakdown.get("screenFlow", []),
            "sharedComponents": breakdown.get("sharedComponents", []),
            "tokens": tokens_tree,
            "dataModel": data_model,
            "templates": TEMPLATES_VERSION,
        },
        sort_keys=True,
        ensure_ascii=False,
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _playbook(app_name, screens, platforms, golden) -> str:
    route_table = "\n".join(
        f"| `{_snake(s['id'])}` | {_pascal(s['id'])}View | "
        f"{s.get('status', 'full')} |"
        + (f" {s['guard']['state']}={s['guard']['value']} |" if s.get("guard") else " — |")
        for s in screens
    ) or "| (no screens) | | | |"
    return f"""# Build Playbook — `{app_name}`

Blueprint golden: `{golden}`
Templates v{TEMPLATES_VERSION} · factory {FACTORY_VERSION} · platforms: {', '.join(platforms)}

## Order of work (roles → gates)
1. **emit** — apply this blueprint into the target dir. Generated layer
   overwrites freely; extension points (View/ViewModel) only if absent.
2. **arch_guard** — must pass before any build (layering, BaseViewModel, Ports,
   Supabase-confined, busy/error on async).
3. **builders** (per resolved platform) — fill the extension-point View/ViewModel
   bodies with native primitives from `breakdown.json`:
   - iOS: glass (UiKitView → Liquid Glass)
   - Android: expressive (AndroidView → ComposeView + MaterialExpressiveTheme)
   - web + desktop: shadcn (`Shad*` from shadcn_ui)
4. **tester** (TDD) — mocktail the Ports; probe-runner visual/smoke; Patrol E2E.
5. **reviewer + QC** — arch_guard + ponytail-debt gate; green ⇒ release-ready.
6. **deployer** — fastlane (stores) + shorebird (OTA patch).

## Screens (from screenFlow)
| route | view | status | guard |
|-------|------|--------|-------|
{route_table}

## Determinism
Generated layer = byte-identical per (design, factory-version). Extension
points carry `@appbox-extension-point` markers; `emit.py` never overwrites them.
Identity across platforms lives in the Token layer (`lib/app_tokens.dart`),
NOT in the widgets — each platform is intentionally native-distinct.
"""


# ----------------------------------------------------------------------------
# Domain Model projections (ADR-0004). One frozen data_model.json is the single
# source of truth; everything below is a deterministic projection of it:
#   entity + Port → Supabase adapter → Drift table + local adapter → cached
#   decorator, plus the Supabase migration + seed SQL. Pure code, no LLM.
# ----------------------------------------------------------------------------

# data_model `type` → (Dart base, Postgres type, Drift column method)
_TYPE_MAP = {
    "uuid": ("String", "uuid", "text"),
    "text": ("String", "text", "text"),
    "int": ("int", "integer", "integer"),
    "integer": ("int", "integer", "integer"),
    "bigint": ("int", "bigint", "integer"),
    "bool": ("bool", "boolean", "boolean"),
    "boolean": ("bool", "boolean", "boolean"),
    "date": ("DateTime", "date", "dateTime"),
    "timestamptz": ("DateTime", "timestamptz", "dateTime"),
    "timestamp": ("DateTime", "timestamp", "dateTime"),
    "numeric": ("double", "numeric", "real"),
    "float": ("double", "double precision", "real"),
    "double": ("double", "double precision", "real"),
}
_DRIFT_GETTER = {"text": "TextColumn", "integer": "IntColumn", "real": "RealColumn",
                 "boolean": "BoolColumn", "dateTime": "DateTimeColumn"}


def _camel(s: str) -> str:
    parts = [p for p in re.split(r"[^0-9a-zA-Z]+", s) if p]
    if not parts:
        return "field"
    return parts[0].lower() + "".join(p[:1].upper() + p[1:] for p in parts[1:])


def _dart_base(f: dict) -> str:
    return _TYPE_MAP.get(f.get("type"), ("String", "text", "text"))[0]


def _nullable(f: dict) -> bool:
    # pk and notNull fields are non-null; everything else is nullable.
    return not (f.get("notNull") or f.get("pk"))


def _dart_type(f: dict) -> str:
    return _dart_base(f) + ("" if not _nullable(f) else "?")


def _entity_fields(entity: dict) -> list:
    # Fields the CLIENT holds: server-only columns (owner user_id, created_at)
    # live in Supabase + RLS, never in the entity or the local cache.
    return [f for f in entity.get("fields", []) if not f.get("serverOnly")]


def _parse_expr(col: str, base: str, nullable: bool) -> str:
    if base == "int":
        return f"(m['{col}'] as num?)?.toInt()" if nullable else f"(m['{col}'] as num).toInt()"
    if base == "double":
        return f"(m['{col}'] as num?)?.toDouble()" if nullable else f"(m['{col}'] as num).toDouble()"
    if base == "bool":
        return f"m['{col}'] as bool?" if nullable else f"m['{col}'] as bool"
    if base == "DateTime":
        if nullable:
            return f"m['{col}'] == null ? null : DateTime.parse(m['{col}'] as String)"
        return f"DateTime.parse(m['{col}'] as String)"
    return f"m['{col}'] as String?" if nullable else f"m['{col}'] as String"


def _entity_dart(entity: dict) -> str:
    cls = _pascal(entity["name"])
    fields = _entity_fields(entity)
    decls = "\n".join(f"  final {_dart_type(f)} {_camel(f['name'])};" for f in fields)
    params = ", ".join(("required " if not _nullable(f) else "")
                       + f"this.{_camel(f['name'])}" for f in fields)
    from_map = ",\n".join(
        f"        {_camel(f['name'])}: {_parse_expr(f['name'], _dart_base(f), _nullable(f))}"
        for f in fields)
    return (
        f"{GEN_MARKER}\n"
        "// Domain entity + repository Port from the Domain Model (data_model.json).\n"
        "// Pure Dart (ADR-0003): NO Flutter, NO Supabase. Infrastructure implements it.\n"
        "\n"
        f"class {cls} {{\n"
        f"{decls}\n"
        f"  const {cls}({{{params}}});\n"
        "\n"
        f"  factory {cls}.fromMap(Map<String, dynamic> m) => {cls}(\n"
        f"{from_map},\n"
        "      );\n"
        "}\n"
        "\n"
        f"/// Repository Port for {cls} (RLS scopes rows to the signed-in user).\n"
        f"abstract class {cls}Repository {{\n"
        f"  Future<List<{cls}>> all();\n"
        "}\n"
    )


def _supabase_adapter_dart(entity: dict) -> str:
    cls = _pascal(entity["name"])
    en = _snake(entity["name"])
    cols = ",".join(f["name"] for f in _entity_fields(entity))
    order = entity.get("orderBy")
    order_line = f".order('{order}')" if order else ""
    # Only `hide` the entity name when it actually clashes with a gotrue symbol
    # exported by supabase_flutter (Session/User). Other names (Profile, Workout,
    # ...) aren't exported, so `hide <Name>` is an undefined_hidden_name warning.
    _clashes = cls in {"Session", "User"}
    _hide = f" hide {cls}" if _clashes else ""
    _hide_note = (
        f"// `hide {cls}` avoids the gotrue symbol clash (Session/User).\n"
        if _clashes
        else f"// No `hide` — {cls} isn't a gotrue symbol, so there's no clash.\n"
    )
    return (
        f"{GEN_MARKER}\n"
        f"// Supabase adapter for {cls} (ADR-0003). Supabase CONFINED to infrastructure.\n"
        f"{_hide_note}"
        f"import 'package:supabase_flutter/supabase_flutter.dart'{_hide};\n"
        "\n"
        f"import '../domain/ports/{en}_repository.dart';\n"
        "\n"
        f"class {cls}RepositorySupabase implements {cls}Repository {{\n"
        "  SupabaseClient get _client => Supabase.instance.client;\n"
        "\n"
        "  @override\n"
        f"  Future<List<{cls}>> all() async {{\n"
        f"    final rows = await _client.from('{entity['table']}').select('{cols}'){order_line};\n"
        "    return (rows as List)\n"
        f"        .map((r) => {cls}.fromMap(r as Map<String, dynamic>))\n"
        "        .toList();\n"
        "  }\n"
        "}\n"
    )


def _drift_column(f: dict) -> str:
    name = _camel(f["name"])
    col = f["name"]
    method = _TYPE_MAP.get(f.get("type"), ("String", "text", "text"))[2]
    getter = _DRIFT_GETTER[method]
    mods = ""
    if col != name:
        mods += f".named('{col}')"
    if _nullable(f):
        mods += ".nullable()"
    return f"  {getter} get {name} => {method}(){mods}();"


def _drift_db_dart(entities: list) -> str:
    blocks = []
    for e in entities:
        tbl = _pascal(e["table"])
        cls = _pascal(e["name"])
        cols = "\n".join(_drift_column(f) for f in _entity_fields(e))
        pk = [_camel(f["name"]) for f in _entity_fields(e) if f.get("pk")]
        pk_line = ("\n  @override\n  Set<Column> get primaryKey => {" + ", ".join(pk) + "};") if pk else ""
        # @DataClassName names the row class <Entity>Row so it never collides with
        # the domain <Entity> entity (drift would otherwise singularize Sessions→Session).
        blocks.append(f"@DataClassName('{cls}Row')\nclass {tbl} extends Table {{\n{cols}{pk_line}\n}}")
    classes = "\n\n".join(blocks)
    table_list = ", ".join(_pascal(e["table"]) for e in entities)
    return (
        f"{GEN_MARKER}\n"
        "// Local persistence (Drift) — all platforms incl. web (WebAssembly sqlite3).\n"
        "// Tables mirror the domain entities; remote-only owner columns (e.g. user_id)\n"
        "// live solely in Supabase + RLS, never in the local cache.\n"
        "import 'package:drift/drift.dart';\n"
        "import 'package:drift_flutter/drift_flutter.dart';\n"
        "\n"
        "part 'app_database.g.dart';\n"
        "\n"
        f"{classes}\n"
        "\n"
        f"@DriftDatabase(tables: [{table_list}])\n"
        "class AppDatabase extends _$AppDatabase {\n"
        "  AppDatabase._() : super(_open());\n"
        "  static final AppDatabase instance = AppDatabase._();\n"
        "\n"
        "  @override\n"
        "  int get schemaVersion => 1;\n"
        "\n"
        "  @override\n"
        "  MigrationStrategy get migration => MigrationStrategy(\n"
        "        onCreate: (m) => m.createAll(),\n"
        "        // ponytail: v1 only. Bump schemaVersion + add stepwise onUpgrade when\n"
        "        // the Domain Model changes (drift migrations guide; verify via its test).\n"
        "        onUpgrade: (m, from, to) async {},\n"
        "      );\n"
        "\n"
        "  static QueryExecutor _open() => driftDatabase(\n"
        "        name: 'app_db',\n"
        "        web: DriftWebOptions(\n"
        "          sqlite3Wasm: Uri.parse('sqlite3.wasm'),\n"
        "          driftWorker: Uri.parse('drift_worker.js'),\n"
        "        ),\n"
        "      );\n"
        "}\n"
    )


def _local_adapter_dart(entity: dict) -> str:
    cls = _pascal(entity["name"])
    en = _snake(entity["name"])
    tbl = _pascal(entity["table"])
    acc = tbl[0].lower() + tbl[1:]
    fields = _entity_fields(entity)
    row = ", ".join(f"{_camel(f['name'])}: Value(s.{_camel(f['name'])})" for f in fields)
    ent = ", ".join(f"{_camel(f['name'])}: r.{_camel(f['name'])}" for f in fields)
    return (
        f"{GEN_MARKER}\n"
        f"// Local (Drift) adapter for {cls}: offline cache mirroring the entity.\n"
        "import 'package:drift/drift.dart';\n"
        "\n"
        f"import '../domain/ports/{en}_repository.dart';\n"
        # hide the Drift-generated table class (named <tbl>, e.g. Session/Profile) from
        # app_database.dart — it clashes with the domain entity of the same name. Without
        # this, both libraries export `Session` → ambiguous_import. The Drift table class
        # is reached via `_db.<table>` + `<tbl>Companion`, not by name, so hiding it is safe.
        f"import 'local/app_database.dart' hide {tbl};\n"
        "\n"
        f"class {cls}RepositoryLocal implements {cls}Repository {{\n"
        "  AppDatabase get _db => AppDatabase.instance;\n"
        "\n"
        f"  {tbl}Companion _row({cls} s) => {tbl}Companion({row});\n"
        "\n"
        f"  Future<void> upsertAll(List<{cls}> items) =>\n"
        "      _db.batch((b) => b.insertAllOnConflictUpdate(\n"
        f"          _db.{acc}, [for (final s in items) _row(s)]));\n"
        "\n"
        "  @override\n"
        f"  Future<List<{cls}>> all() async {{\n"
        f"    final rows = await _db.select(_db.{acc}).get();\n"
        f"    return [for (final r in rows) {cls}({ent})];\n"
        "  }\n"
        "}\n"
    )


def _cached_adapter_dart(entity: dict) -> str:
    cls = _pascal(entity["name"])
    en = _snake(entity["name"])
    return (
        f"{GEN_MARKER}\n"
        f"// Read-through cache for {cls}: remote (Supabase) refreshes the local (Drift)\n"
        "// store on every read; offline → serve the cached rows.\n"
        "// ponytail: read-through ONLY — no offline writes / conflict resolution. For\n"
        "// bidirectional sync use PowerSync (works on Drift) — swap this binding.\n"
        f"import '../domain/ports/{en}_repository.dart';\n"
        f"import '{en}_repository_supabase.dart';\n"
        f"import '{en}_repository_local.dart';\n"
        "\n"
        f"class {cls}RepositoryCached implements {cls}Repository {{\n"
        f"  final _remote = {cls}RepositorySupabase();\n"
        f"  final _local = {cls}RepositoryLocal();\n"
        "\n"
        "  @override\n"
        f"  Future<List<{cls}>> all() async {{\n"
        "    try {\n"
        "      final rows = await _remote.all();\n"
        "      try {\n"
        "        await _local.upsertAll(rows);\n"
        "      } catch (_) {\n"
        "        // best-effort cache (e.g. web without the Drift wasm assets)\n"
        "      }\n"
        "      return rows;\n"
        "    } catch (_) {\n"
        "      try {\n"
        "        return await _local.all();\n"
        "      } catch (_) {\n"
        f"        return const <{cls}>[];\n"
        "      }\n"
        "    }\n"
        "  }\n"
        "}\n"
    )


def _sql_column(f: dict) -> str:
    sqlt = _TYPE_MAP.get(f.get("type"), (None, "text", None))[1]
    s = f"{f['name']} {sqlt}"
    if f.get("pk"):
        s += " primary key"
    if f.get("default"):
        s += f" default {f['default']}"
    if f.get("references"):
        s += f" references {f['references']}(id) on delete cascade"
    if f.get("notNull") and not f.get("pk"):
        s += " not null"
    return s


def _migration_sql(entities: list) -> str:
    out = ["-- AUTO-GENERATED by flutter_crew from data_model.json — schema + RLS.",
           "-- Apply via the Supabase MCP: apply_migration(name, <this file>).",
           "create extension if not exists pgcrypto;", ""]
    for e in entities:
        t = e["table"]
        cols = ",\n".join("  " + _sql_column(f) for f in e["fields"])
        out.append(f"create table if not exists public.{t} (\n{cols}\n);")
        out.append(f"alter table public.{t} enable row level security;")
        owner = next((f["name"] for f in e["fields"] if f.get("owner")), None)
        if owner:
            out.append(f'drop policy if exists "{t}_rw_own" on public.{t};')
            out.append(f'create policy "{t}_rw_own" on public.{t}\n'
                       "  for all to authenticated\n"
                       f"  using ((select auth.uid()) = {owner})\n"
                       f"  with check ((select auth.uid()) = {owner});")
        else:
            out.append(f'drop policy if exists "{t}_read_auth" on public.{t};')
            out.append(f'create policy "{t}_read_auth" on public.{t} '
                       "for select to authenticated using (true);")
        out.append("")
    return "\n".join(out) + "\n"


def _sql_val(v) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


def _auth_user_sql(uid: str, email: str, pw: str) -> str:
    return (
        "-- Test auth user (dev/demo login). pgcrypto provides crypt()/gen_salt().\n"
        "insert into auth.users (\n"
        "  id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,\n"
        "  created_at, updated_at, raw_app_meta_data, raw_user_meta_data,\n"
        "  confirmation_token, recovery_token, email_change, email_change_token_new,\n"
        "  reauthentication_token\n"
        ") values (\n"
        f"  '{uid}', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',\n"
        f"  '{email}', crypt('{pw}', gen_salt('bf')), now(), now(), now(),\n"
        "  '{\"provider\":\"email\",\"providers\":[\"email\"]}', '{}', '', '', '', '', ''\n"
        ") on conflict do nothing;\n"
        "\n"
        "insert into auth.identities (\n"
        "  id, user_id, provider_id, identity_data, provider, last_sign_in_at,\n"
        "  created_at, updated_at\n"
        ") values (\n"
        f"  gen_random_uuid(), '{uid}', '{uid}',\n"
        f"  '{{\"sub\":\"{uid}\",\"email\":\"{email}\",\"email_verified\":true}}', 'email', now(), now(), now()\n"
        ") on conflict do nothing;\n"
    )


def _seed_uuid(i: int) -> str:
    """Deterministic per-row uuid (idempotent seed: fixed uuids + on conflict do nothing).
    Mirrors the legacy '5e551000-…-0001' pattern so re-seeds collide instead of duplicating."""
    return f"5e551000-0000-4000-8000-{i + 1:012d}"


def _date_from_last(last, anchor: str) -> str:
    """A design 'last activity' phrase → an ISO date, parsed against a FIXED anchor (NOT
    today — determinism: seed.sql must not churn run-to-run). 'Yesterday'→-1, 'Nd ago'→-N,
    'Nw ago'→-7N, else the anchor itself."""
    from datetime import date, timedelta
    y, m, d = (int(x) for x in anchor.split("-"))
    base = date(y, m, d)
    s = str(last or "").strip().lower()
    days = 0
    if s == "yesterday":
        days = 1
    else:
        mt = re.match(r"(\d+)\s*([dw])", s)
        if mt:
            days = int(mt.group(1)) * (7 if mt.group(2) == "w" else 1)
    return (base - timedelta(days=days)).isoformat()


def _design_seed(data_model_path, source: str) -> list:
    """The design's OWN seed rows, extracted from `data.jsx` (the design IS the seed
    source — user's data flow: design → seed → DB). Resolved as a sibling of the
    Domain-Model file: <data_model dir>/design/data.jsx. [] when absent (snapshot fixture)."""
    if not data_model_path:
        return []
    djsx = os.path.join(os.path.dirname(os.path.abspath(data_model_path)), "design", "data.jsx")
    if not os.path.exists(djsx):
        return []
    from capture_data import extract_data_model  # sibling stage; standalone (no cycle)
    with open(djsx, encoding="utf-8") as f:
        return extract_data_model(f.read(), source).get("seed") or []


def _project_seed_rows(entity: dict, design_seed: list, auth_user: dict) -> list:
    """Project the design's seed rows onto a DB entity's columns via its declared
    `seedFrom` map (column ← design field) — the 'builder makes the DB from the seed'
    step. Columns the design can't supply are synthesized: pk uuid (deterministic),
    owner ← auth user, a date column ← the design's 'last' phrase. No seedFrom →
    the entity's literal `seed` (e.g. the singleton profile)."""
    spec = entity.get("seedFrom")
    if not spec:
        return entity.get("seed") or []
    colmap = spec.get("map", {})
    datecfg = spec.get("date") or {}
    owner = next((f["name"] for f in entity["fields"] if f.get("owner")), None)
    rows = []
    for i, dr in enumerate(design_seed):
        row = {}
        for f in entity["fields"]:
            n = f["name"]
            if f.get("pk") and f.get("type") == "uuid" and not f.get("references"):
                row[n] = _seed_uuid(i)
            elif n == owner and auth_user:
                row[n] = auth_user["id"]
            elif n in colmap and colmap[n] in dr:
                row[n] = dr[colmap[n]]
            elif n == datecfg.get("column"):
                row[n] = _date_from_last(dr.get(datecfg.get("from")), datecfg.get("anchor"))
            # else: column omitted → takes its DB default (e.g. created_at)
        rows.append(row)
    return rows


def _seed_sql(entities: list, auth_user: dict, data_model_path=None) -> str:
    out = ["-- AUTO-GENERATED seed — re-runnable: design-sourced rows are DELETE-then-",
           "-- inserted per auth user (so re-seeding reflects the current design); fixed uuids.",
           "-- Seed VALUES come from the design itself (design/data.jsx), projected onto the",
           "-- schema; the Domain Model declares only structure. Apply: execute_sql(<this file>).", ""]
    if auth_user:
        out.append(_auth_user_sql(auth_user["id"], auth_user["email"], auth_user["password"]))
    # The design's seed, shared by every design-sourced entity (projected per its seedFrom map).
    design_source = next((e["seedFrom"]["source"] for e in entities
                          if e.get("seedFrom", {}).get("source")), None)
    design_seed = _design_seed(data_model_path, design_source) if design_source else []
    for e in entities:
        rows = _project_seed_rows(e, design_seed, auth_user)
        if not rows:
            continue
        cols = list(rows[0].keys())
        values = ",\n  ".join(
            "(" + ", ".join(_sql_val(r.get(c)) for c in cols) + ")" for r in rows)
        # Design-sourced rows are RE-DERIVED from the design every build, so a re-seed
        # must REPLACE the auth user's rows — `on conflict do nothing` left stale rows
        # with the same uuid but old values (the "wrong seed data again" bug: the cloud
        # kept Core Circuit/Zone 2 Ride forever). DELETE-then-insert, scoped to the seed
        # user; auth.users/identities/profiles are NOT design-sourced → left untouched.
        if e.get("seedFrom") and auth_user and "user_id" in cols:
            out.append(
                f"delete from public.{e['table']} where user_id = {_sql_val(auth_user['id'])};")
        out.append(f"insert into public.{e['table']} ({', '.join(cols)}) values\n  {values}\n"
                   "on conflict do nothing;")
        out.append("")
    return "\n".join(out) + "\n"


def _load_data_model(path) -> dict:
    if not path or not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as f:
        doc = json.load(f)
    # Unwrap the `data_model` wrapper (capture_data emits {"data_model": {...}, "state": {...}};
    # ADR-0012 designer-authored shape is the same). Callers read `entities`/`fields`/
    # `seed` at the TOP level of the model, so return the inner model, not the wrapper.
    # Without this, `data_model.get("entities")` returned None (entities nested under
    # data_model.entities) → blueprint silently emitted NO entity repositories, and the
    # generated views that reference Session/ProfileRepository failed G5. Matches
    # parity.seed_rows' unwrap (doc.get("data_model", doc)).
    if isinstance(doc, dict) and isinstance(doc.get("data_model"), dict):
        return doc["data_model"]
    return doc


def assemble(breakdown: dict, out_dir: str, tokens_path=None,
             factory_version=FACTORY_VERSION, generated="2026-06-20T00:00:00Z",
             stack="stacked", app_name_override=None, data_model_path=None,
             backend=None) -> dict:
    meta = breakdown.get("meta", {})
    source = meta.get("source", "app")
    app_name = _app_name(source, app_name_override)
    display_name = _app_display_name(source, app_name_override)
    platforms = meta.get("platforms") or ["ios", "android", "web"]
    screens = breakdown.get("screenFlow") or []
    primary_nav = breakdown.get("primaryNav")  # the design's bottom-TabBar manifest (or None)
    data_model = _load_data_model(data_model_path)
    entities = data_model.get("entities") or []

    os.makedirs(out_dir, exist_ok=True)
    tdir = os.path.join(out_dir, "templates")
    lib = os.path.join(tdir, "lib")
    for d in (
        os.path.join(lib, "app"),
        os.path.join(lib, "ui"),
        os.path.join(lib, "domain", "ports"),
        os.path.join(lib, "application"),
        os.path.join(lib, "infrastructure"),
        os.path.join(lib, "presentation"),
        os.path.join(tdir, "test"),
    ):
        os.makedirs(d, exist_ok=True)

    # --- generated layer ---
    gen = {
        "lib/main.dart": _tpl_main(display_name),
        "lib/app/app.dart": _tpl_app(app_name, screens, platforms, entities, primary_nav),
        "lib/ui/render_strategy.dart": _tpl_render_strategy(),
        "lib/ui/primitives.dart": _tpl_primitives(
            [k for k, v in _BRAND_REGISTRY.items() if v.get("colorMode") == "mono"],
            {k: v.get("platforms") for k, v in _BRAND_REGISTRY.items()
             if v.get("platforms")}),
        "lib/ui/feedback_service.dart": _tpl_feedback_service(),
        "lib/ui/app_theme.dart": _tpl_theme(),
        "lib/domain/ports/repository.dart": _tpl_ports(),
        "lib/infrastructure/supabase_client.dart": _tpl_supabase_client(),
        "lib/infrastructure/supabase_auth_service.dart": _tpl_supabase_auth(
            (backend or {}).get("authMethods") or _BACKEND_AUTH_DEFAULT),
        "lib/infrastructure/base_supabase_repository.dart": _tpl_base_repo(),
        "pubspec.yaml": _tpl_pubspec(
            app_name, source,
            (backend or {}).get("authMethods") or _BACKEND_AUTH_DEFAULT),
        "analysis_options.yaml": _tpl_analysis_options(),
    }
    # The root nav shell — emitted ONLY when the design declares a primaryNav (bottom
    # TabBar). Hosts the tab destinations in an IndexedStack under an AdaptiveTabBar.
    # Absent → no shell (the app stays flat: every screen a top-level route). No regression.
    if primary_nav and primary_nav.get("tabs"):
        tab_ids = [t["id"] for t in primary_nav["tabs"]]
        tab_screens = [s for s in screens if s.get("id") in set(tab_ids)]
        if tab_screens:
            gen["lib/presentation/home_shell_view.dart"] = _tpl_nav_shell_view(
                tab_screens, primary_nav)
            gen["lib/presentation/root_navigation_viewmodel.dart"] = _tpl_nav_shell_vm(
                tab_screens, primary_nav)
    # token layer (generated) — real tokens if provided, else stub
    tokens_dart = _load_tokens_dart(tokens_path)
    gen["lib/app_tokens.dart"] = tokens_dart if tokens_dart else _tokens_stub()

    # --- Domain Model projections (generated, ADR-0004) — per-entity Port +
    # entity, Supabase (remote) + Drift (local) adapters, a read-through cache,
    # the local Drift database, and the Supabase migration + seed SQL. One frozen
    # data_model.json is the single source of truth for all of them. ---
    for e in entities:
        en = _snake(e["name"])
        gen[f"lib/domain/ports/{en}_repository.dart"] = _entity_dart(e)
        gen[f"lib/infrastructure/{en}_repository_supabase.dart"] = _supabase_adapter_dart(e)
        gen[f"lib/infrastructure/{en}_repository_local.dart"] = _local_adapter_dart(e)
        gen[f"lib/infrastructure/{en}_repository_cached.dart"] = _cached_adapter_dart(e)
    if entities:
        gen["lib/infrastructure/local/app_database.dart"] = _drift_db_dart(entities)
        gen["supabase/migrations/0001_init.sql"] = _migration_sql(entities)
        gen["supabase/seed.sql"] = _seed_sql(entities, data_model.get("authUser"), data_model_path)

    # --- extension points (one View + ViewModel per screen) ---
    ext = {}
    for s in screens:
        snake = _snake(s["id"])
        ext[f"lib/presentation/{snake}_view.dart"] = _tpl_view(s)
        ext[f"lib/presentation/{snake}_viewmodel.dart"] = _tpl_viewmodel(s)

    # --- brand sign-in glyphs (factory-owned assets, NOT design-extracted) ---
    # A social CTA ("Continue with Google/Apple/…") renders NATIVE on every family.
    # The mark is detected from the breakdown (props.name) and rasterized ONCE to a
    # PNG via rsvg-convert — that PNG is the canonical asset every native platform
    # renders (iOS UIKit decode + Android Compose BitmapPainter), so iOS and Android
    # produce byte-identical marks with no per-platform redraw and no hand-drawn
    # Canvas beziers (the bezier path produced a misshapen Google G). The SVG sibling
    # feeds the shadcn/web path. colorMode per brand drives the tint rule (brand-fixed
    # colors vs mono-tinted-to-fg), dictated by each brand's own guidelines.
    detected = _detected_brands(breakdown)
    _emit_brand_pngs(gen, detected)

    written = []
    for rel, content in {**gen, **ext}.items():
        path = os.path.join(tdir, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if isinstance(content, bytes):
            with open(path, "wb") as f:
                f.write(content)
        else:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
        written.append(rel)

    # --- tokens tree (for golden + manifest) ---
    tokens_tree = {}
    if tokens_path and os.path.exists(tokens_path):
        try:
            with open(tokens_path, encoding="utf-8") as f:
                tokens_tree = json.load(f)
        except Exception:
            tokens_tree = {}

    golden = _golden(breakdown, tokens_tree, data_model)

    manifest = {
        "factoryVersion": factory_version,
        "source": source,
        "stack": stack,
        "lastMode": "new-app",
        "blueprintHash": golden,
        "templatesVersion": TEMPLATES_VERSION,
        "generated": generated,
        "platforms": platforms,
        "crewVersion": meta.get("crewVersion"),
        "appName": app_name,
        "displayName": display_name,
        "generatedLayer": sorted(gen.keys()),
        "extensionPoints": sorted(ext.keys()),
        "screens": [
            {"id": s["id"], "class": _pascal(s["id"]), "route": _snake(s["id"]),
             "status": s.get("status", "full")}
            for s in screens
        ],
    }
    with open(os.path.join(out_dir, "manifest.json"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")
    with open(os.path.join(out_dir, "golden.sha256"), "w", encoding="utf-8") as f:
        f.write(golden + "\n")
    with open(os.path.join(out_dir, "playbook.md"), "w", encoding="utf-8") as f:
        f.write(_playbook(app_name, screens, platforms, golden))

    return {"manifest": manifest, "generated": len(gen),
            "extension": len(ext), "golden": golden, "app": app_name,
            "display": display_name}


def _self_test():
    """Behaviour assertions for the pure template fragments. blueprint.py is a
    large synthesis (not a single pure transform), so this targets the fragments
    that have bitten us — today: `_tpl_analysis_options` must exclude the cruft
    that otherwise poisons `dart analyze` (the blueprint-package `templates/` dir
    and the stale `flutter create` widget_test.dart). Grow this as more fragments
    earn behaviour coverage."""
    ao = _tpl_analysis_options()
    # the gen marker is present (so emit treats it as generated, not preserved)
    assert "AUTO-GENERATED" in ao, "analysis_options missing GEN_MARKER"
    # the two analyzer-blocking cruft paths are excluded
    assert "templates/**" in ao, \
        "analysis_options must exclude templates/** (blueprint-package cruft)"
    assert "test/widget_test.dart" in ao, \
        "analysis_options must exclude the stale flutter-create widget_test.dart"
    # flutter_lints include is still there (didn't accidentally drop it)
    assert "package:flutter_lints/flutter.yaml" in ao

    # pubspec must declare flutter_svg directly — generated views import it
    # (SVG leaves + brand glyphs at blueprint.py:567, generate_view.py:2507/3042),
    # so it's a real dependency, not transitive. Without this, every importing
    # view trips `depend_on_referenced_packages`.
    assert "flutter_svg" in PUBSPEC_DEPS, \
        "flutter_svg must be a declared pubspec dep (generated code imports it directly)"

    # l10n wiring (unconditional): flutter_localizations as an sdk dep, intl for
    # the gen-l10n messages API, and `generate: true` so gen-l10n runs on pub get.
    ps = _tpl_pubspec("selftest_app", "breakdown.json")
    assert PUBSPEC_DEPS.get("flutter_localizations") == {"sdk": "flutter"}, \
        "flutter_localizations must be declared as an sdk dep"
    assert "intl" in PUBSPEC_DEPS, "intl must be a declared pubspec dep"
    assert "  flutter_localizations:\n    sdk: flutter" in ps, \
        "pubspec must render flutter_localizations as a nested sdk entry"
    assert "\n  intl: any\n" in ps, "pubspec must render intl as a hosted dep"
    assert "\n  generate: true" in ps, \
        "pubspec flutter: section must set generate: true (gen-l10n on pub get)"
    print("blueprint._self_test: OK (analysis_options excludes cruft; flutter_svg declared; "
          "l10n deps + generate: true)")
    return 0


def main(argv):
    if "--self-test" in argv:
        return _self_test()
    if len(argv) < 3:
        print("usage: blueprint.py <breakdown.json> <out-dir> "
              "[--tokens tokens.json] [--data-model data_model.json] "
              "[--factory-version V] [--generated ISO] "
              "[--stack stacked] [--app-name NAME]", file=sys.stderr)
        return 2
    breakdown_path, out_dir = argv[1], argv[2]
    with open(breakdown_path, encoding="utf-8") as f:
        breakdown = json.load(f)

    tokens_path = None
    data_model_path = None
    factory_version = FACTORY_VERSION
    generated = "2026-06-20T00:00:00Z"
    stack = "stacked"
    app_name_override = None
    handlers_path = None
    config_path = None
    i = 3
    while i < len(argv):
        a = argv[i]
        if a == "--tokens" and i + 1 < len(argv):
            tokens_path = argv[i + 1]; i += 2
        elif a == "--data-model" and i + 1 < len(argv):
            data_model_path = argv[i + 1]; i += 2
        elif a == "--factory-version" and i + 1 < len(argv):
            factory_version = argv[i + 1]; i += 2
        elif a == "--generated" and i + 1 < len(argv):
            generated = argv[i + 1]; i += 2
        elif a == "--stack" and i + 1 < len(argv):
            stack = argv[i + 1]; i += 2
        elif a == "--app-name" and i + 1 < len(argv):
            app_name_override = argv[i + 1]; i += 2
        elif a == "--handlers" and i + 1 < len(argv):
            handlers_path = argv[i + 1]; i += 2
        elif a == "--config" and i + 1 < len(argv):
            config_path = argv[i + 1]; i += 2
        else:
            i += 1

    # backend resolve (ADR-0013): handlers co-located with the breakdown by
    # default; auth methods = design-derived ∪ operator config.
    if handlers_path is None:
        cand = os.path.join(os.path.dirname(os.path.abspath(breakdown_path)), "handlers.json")
        handlers_path = cand if os.path.exists(cand) else None
    handlers = {}
    if handlers_path and os.path.exists(handlers_path):
        with open(handlers_path, encoding="utf-8") as f:
            handlers = json.load(f)
    config = {}
    if config_path and os.path.exists(config_path):
        with open(config_path, encoding="utf-8") as f:
            config = json.load(f)
    backend = _backend_cfg(config, handlers)

    r = assemble(breakdown, out_dir, tokens_path, factory_version, generated,
                 stack, app_name_override, data_model_path, backend)
    m = r["manifest"]
    print(f"blueprint → {out_dir}")
    print(f"  app={r['app']} display={r['display']} golden={r['golden'][:12]}…")
    print(f"  generated-layer={r['generated']} extension-points={r['extension']} "
          f"screens={len(m['screens'])} platforms={','.join(m['platforms'])}")
    print(f"  manifest + golden.sha256 + playbook.md written")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
